-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 18: Recursão — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('0133d39b-82d1-5030-a392-ea9c68eee66d', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Uma solução recursiva precisa normalmente de:', '["Somente variáveis static.","Caso básico e progressão em direção a ele.","Ausência de argumentos.","Uma interface gráfica.","Um loop infinito."]'::jsonb, 1, 'Sem término adequado, chamadas podem continuar até esgotar recursos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.2, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('576d69e2-9967-5c71-96ea-d541bac7739d', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Para f(0)=1 e f(n)=n*f(n-1), qual é f(4)?', '["16.","4.","24.","0.","12."]'::jsonb, 2, 'O cálculo é 4*3*2*1.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.3, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('667d2e1a-8a71-564a-8c57-34204c2be7dd', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual valor de f(0) na definição usual de fatorial?', '["-1.","0.","1.","10.","Indefinido necessariamente."]'::jsonb, 2, 'O caso básico permite encerrar a expansão recursiva.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.3, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1490a30f-4ce0-545b-aaff-64513b2a0e1b', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Chamar f(n-1) sem verificar n negativo em um fatorial definido apenas para n não negativo pode:', '["Impedir atingir o caso básico previsto.","Impedir compilação obrigatoriamente.","Produzir sempre zero imediatamente.","Corrigir automaticamente a entrada.","Criar um array."]'::jsonb, 0, 'O domínio de entrada precisa ser validado conforme o algoritmo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.3, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6edd1970-dc0b-5bc2-8e90-663c56c610db', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'BigInteger é útil para fatoriais grandes porque:', '["Representa inteiros de precisão arbitrária limitada pelos recursos.","É sempre mais rápido que int.","Converte todo resultado em double.","Não usa memória.","Aceita apenas números de até 32 bits."]'::jsonb, 0, 'Int e long possuem limites fixos de representação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.4, páginas 646 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e3a257af-fe0e-57f7-9f3b-202643342159', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Com F(0)=0, F(1)=1 e F(n)=F(n-1)+F(n-2), qual é F(6)?', '["6.","21.","5.","13.","8."]'::jsonb, 4, 'A sequência inicial é 0,1,1,2,3,5,8.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.5, páginas 647–648 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('541837b7-d1e0-5c1d-8236-703187a3bcf5', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Difícil', 'A implementação ingênua recursiva de Fibonacci repete muito trabalho por:', '["Não possuir casos básicos possíveis.","Recalcular os mesmos subproblemas.","Ordenar os resultados.","Usar apenas um quadro de pilha.","Eliminar as chamadas anteriores."]'::jsonb, 1, 'O número de chamadas cresce rapidamente sem reutilização de resultados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.5, páginas 647–648 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c01b7dfa-1fe0-5c6e-b1e9-68efc66c71e5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Chamadas recursivas possuem variáveis locais:', '["Sempre globais e únicas.","Inexistentes.","Compartilhadas como static por definição.","Sem tipo.","Próprias de cada ativação."]'::jsonb, 4, 'Cada quadro de chamada preserva seu contexto local.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.6, páginas 649–650 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d02b45f0-2be2-5c38-9277-6e033dac6a6e', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Difícil', 'Recursão muito profunda pode lançar:', '["Um erro de sintaxe.","IOException obrigatória.","ClassCastException sempre.","Nenhuma falha possível.","StackOverflowError."]'::jsonb, 4, 'A pilha de chamadas possui recursos limitados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.6, páginas 649–650 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01254784-8afc-55c4-b667-9ac5926ec295', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Ao retornar de um caso básico, o fluxo:', '["Apaga todos os resultados.","Torna-se paralelo obrigatoriamente.","Cria novos parâmetros globais.","Retoma as chamadas pendentes em ordem de retorno.","Reinicia automaticamente main."]'::jsonb, 3, 'Cada chamador prossegue após sua chamada recursiva.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.6, páginas 649–650 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('80146dea-cfb6-5d96-a6d4-d3e6e0566658', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Toda solução recursiva é necessariamente mais rápida que a iterativa?', '["Somente para números positivos.","Sim, por usar a pilha.","Sim, sempre.","Não.","Não, porque recursão não executa."]'::jsonb, 3, 'O custo depende do algoritmo e de sua implementação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.7, páginas 651 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a9fbf281-8df1-5fc5-a1bb-6767062438a8', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Uma versão iterativa de fatorial pode evitar principalmente:', '["Um quadro de chamada adicional para cada nível.","Todo risco de overflow numérico.","Qualquer variável local.","A necessidade de entrada válida.","Toda multiplicação."]'::jsonb, 0, 'Trocar recursão por iteração não altera os limites de int ou long.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.7, páginas 651 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e1618278-232c-5ba3-908e-9e3388c43aec', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Para somar de n até zero, qual chamada avança para o caso básico com n positivo?', '["soma(n+1).","soma(2*n).","soma(n).","soma(n+2).","soma(n-1)."]'::jsonb, 4, 'O argumento diminui em direção ao zero.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.2, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('83c61827-0cbe-52ee-b0c6-cf91f8be848d', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Se s(0)=0 e s(n)=n+s(n-1), qual é s(4)?', '["10.","24.","6.","16.","4."]'::jsonb, 0, 'O resultado soma 4, 3, 2 e 1.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.2, páginas 644–645 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eb90dff2-209d-52f8-853e-755c1e110626', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'O número mínimo de movimentos de Hanói com n discos é:', '["n mais 1.","2 elevado a n, menos 1.","n ao quadrado.","n fatorial.","2n."]'::jsonb, 1, 'A recorrência é T(n)=2T(n-1)+1.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.8, páginas 652–653 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eb6a9252-0627-5279-9a68-b3d92314f1ca', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Quantos movimentos mínimos são necessários em Hanói com três discos?', '["6.","9.","8.","7.","3."]'::jsonb, 3, 'Aplicando 2^3-1, obtêm-se sete movimentos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.8, páginas 652–653 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4dc22e8a-7ab8-5594-a842-79b4caad1cee', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Fractais se relacionam à recursão por:', '["Exigência de números inteiros apenas.","Ausência de qualquer padrão.","Repetição de estruturas semelhantes em escalas menores.","Eliminação de casos básicos.","Armazenamento obrigatório em arquivo."]'::jsonb, 2, 'Desenhos recursivos reduzem o problema até uma profundidade ou escala limite.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.9, páginas 654–660 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('32f0300f-28b5-560d-b8d1-53421ebb5a6f', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Backtracking consiste em:', '["Transformar cada escolha em thread.","Retornar a escolhas anteriores quando um caminho falha.","Aceitar obrigatoriamente a primeira escolha.","Executar apenas loops sem condição.","Excluir todos os casos básicos."]'::jsonb, 1, 'A busca pode explorar alternativas após desfazer uma decisão.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.10, páginas 661 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('07df3df5-fc5d-5a63-85e3-992e3826e04e', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Marcar posições já visitadas em uma busca de labirinto pode ajudar a:', '["Garantir sempre caminho único.","Dispensar teste de destino.","Eliminar todos os caminhos válidos.","Evitar ciclos e exploração repetida indevida.","Criar um novo labirinto."]'::jsonb, 3, 'A marcação precisa ser coerente com a estratégia de busca adotada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.10, páginas 661 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b69cca01-fcd1-54f9-9f53-1c732023ab9a', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Difícil', 'Qual análise distingue memória da pilha e tempo de execução recursivo?', '["A pilha não consome memória.","São sempre o mesmo número.","São custos diferentes e devem ser avaliados separadamente.","Toda recursão usa espaço constante.","Tempo depende apenas do nome do método."]'::jsonb, 2, 'Profundidade de chamadas e quantidade total de chamadas podem ter crescimentos distintos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 18, seção 18.7, páginas 651 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
